import React from 'react';
import { Card, CardContent, Box, Typography, useTheme, useMediaQuery, CircularProgress } from '@mui/material';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
} from 'recharts';

const ServerInfoLineChart = ({
  title,
  data,
  dataKey,
  color = '#8884d8',
  sx,
  yAxisTickFormatter,
  tooltipFormatter,
  loading = false,
}) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const formatXAxis = (value) => {
    return value;
  };

  const formatTooltipLabel = (label) => label;
  const gradientId = React.useMemo(() => `gradient_${(title || '').replace(/[^a-zA-Z0-9]/g, '_')}_${dataKey}`, [title, dataKey]);
  const hasData = Array.isArray(data) && data.length > 0;

  // Track selected point index and render custom dots
  const [selectedIndex, setSelectedIndex] = React.useState(null);
  const handleClick = React.useCallback((state) => {
    if (state && typeof state.activeTooltipIndex === 'number') {
      setSelectedIndex(state.activeTooltipIndex);
    }
  }, []);

  const renderDot = React.useCallback(
    (props) => {
      const { cx, cy, index } = props;
      const isSelected = index === selectedIndex;
      const radius = isSelected ? 4 : 3;
      if (isSelected) {
        return (
          <circle cx={cx} cy={cy} r={radius} fill={color} stroke={color} strokeWidth={2} />
        );
      }
      return (
        <circle
          cx={cx}
          cy={cy}
          r={radius}
          fill={theme.palette.background.paper}
          stroke={color}
          strokeWidth={2}
        />
      );
    },
    [selectedIndex, color, theme]
  );

  return (
    <Card sx={{ 
      width: '100%', 
      height: 260, 
      position: 'relative', 
      '& .recharts-surface:focus': {
        outline: 'none',
        boxShadow: 'none'
      },
      '& .recharts-surface:focus-visible': {
        outline: 'none',
        boxShadow: 'none'
      },
      ...sx 
    }}>
      {/* 右上角加载指示，与 ServerInfoWidget 保持一致的风格 */}
      {loading && (
        <Box
          sx={{
            position: 'absolute',
            top: isMobile ? 16 : 24,
            right: isMobile ? 16 : 24,
            zIndex: 1,
          }}
        >
          <CircularProgress size={20} color="primary" />
        </Box>
      )}
      <Box sx={{ p: 2,  pb: 0 }}>
        <Typography 
          variant="h6" 
          gutterBottom 
          sx={{ 
            mb: 2, 
            fontWeight: 'bold',
            fontSize: '1rem'
          }}
        >
          {title}
        </Typography>
      </Box>
      <CardContent sx={{ height: 200, pl: 1, pr: 1 }}>
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={data} margin={{ top: 5, right: 15, left: 5, bottom: 5 }} onClick={handleClick}>
            <defs>
              <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor={color} stopOpacity={0.25} />
                <stop offset="95%" stopColor={color} stopOpacity={0} />
              </linearGradient>
            </defs>
            <XAxis 
              dataKey="date" 
              tickFormatter={formatXAxis} 
              hide={loading || !hasData}
              tickLine={false}
              tick={{ fontSize: 12, fill: theme.palette.text.secondary }}
              dy={10}
            />
            <YAxis 
              allowDecimals={false} 
              tickFormatter={yAxisTickFormatter} 
              hide={loading || !hasData}
              tickLine={false}
              tick={{ fontSize: 12, fill: theme.palette.text.secondary }}
              width={30}
            />
            <Tooltip 
              labelFormatter={formatTooltipLabel} 
              formatter={tooltipFormatter}
              contentStyle={{ background: 'transparent', border: 'none', boxShadow: 'none', padding: 0 }}
              labelStyle={{ color: 'inherit', fontWeight: 500 }}
              itemStyle={{ color: 'inherit' }}
              wrapperStyle={{ outline: 'none' }}
            />
            <Area
              type="monotone"
              dataKey={dataKey}
              stroke={color}
              strokeWidth={2}
              fillOpacity={1}
              fill={`url(#${gradientId})`}
              dot={renderDot}
              activeDot={{ r: 5, fill: color, stroke: color }}
            />
          </AreaChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
};

export default ServerInfoLineChart;

