import React from 'react';
import { 
  Box, 
  Card, 
  CardContent, 
  Typography, 
  Grid,
  LinearProgress,
  Chip,
  CircularProgress,
  IconButton,
  TextField,
  useTheme,
  useMediaQuery
} from '@mui/material';
import { 
  Memory as MemoryIcon,
  Storage as StorageIcon,
  Speed as CpuIcon,
  Api as ApiIcon,
  Person as PersonIcon,
  Article as ArticleIcon,
  SmartToy as ChatbotIcon,
  LocationOn as LocationIcon,
  Refresh as RefreshIcon
} from '@mui/icons-material';
import { SettingsContext } from '../../context/SettingsContext';
import { useContext } from 'react';

const ServerInfoWidget = ({ 
  title, 
  data, 
  loading = false, 
  sx = {}, 
  onRefresh, 
  apiMax7 = 0,
  datePickerEnabled = false,
  selectedDate,
  onDateChange,
}) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  
  const { language, themeMode } = useContext(SettingsContext);

  const formatPercentage = (value, total) => {
    if (total === 0) return 0;
    return Math.round((value / total) * 100);
  };

  const calculateMemoryUsage = (usage, available) => {
    if (available === 0) return 0;
    return Math.round((usage / (usage + available)) * 100);
  };

  const formatNumber = (num) => {
    if (num >= 1000000) {
      return (num / 1000000).toFixed(1) + 'M';
    } else if (num >= 1000) {
      return (num / 1000).toFixed(1) + 'K';
    }
    return num.toString();
  };

  const getProgressColor = (percentage) => {
    if (percentage >= 80) return 'error';
    if (percentage >= 50) return 'warning';
    return 'success';
  };

  // 格式化日期
  const formatDate = (dateString) => {
    if (!dateString) return '';
    
    const date = new Date(dateString);
    if (language === 'cn') {
      // 中文格式: yyyy/mm/dd
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const day = String(date.getDate()).padStart(2, '0');
      return `${year}/${month}/${day}`;
    } else {
      // 英文格式: dd/mm/yyyy
      const day = String(date.getDate()).padStart(2, '0');
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const year = date.getFullYear();
      return `${day}/${month}/${year}`;
    }
  };

  // 使用默认数据确保尺寸不变化
  const defaultData = {
    cpuUsage: 0,
    memoryUsage: 0,
    memoryFree: 0,
    memoryAvailable: 0,
    diskUsage: 0,
    diskFree: 0,
    apiCount: 0,
    anonymousCount: 0,
    blogCount: 0,
    chatbotCount: 0,
    myIpCount: 0,
    reportDate: null
  };

  // 使用数据或默认数据
  const displayData = data || defaultData;

  return (
    <Card sx={{ 
      minWidth: isMobile ? '100%' : 400, 
      maxWidth: isMobile ? '100%' : 500,
      width: isMobile ? '100%' : 'auto',
      height: 'fit-content',
      position: 'relative',
      ...sx 
    }}>
      {/* 右上角的日期或加载状态 */}
      <Box
        sx={{
          position: 'absolute',
          top: isMobile ? 12 : 20,
          right: isMobile ? 8 : 16,
          zIndex: 1,
          // 确保在小屏幕上不会溢出
          maxWidth: isMobile ? 'calc(100% - 16px)' : 'auto',
        }}
      >
        {loading ? (
          <CircularProgress size={20} color="primary" />
        ) : title === 'Now' ? (
          <IconButton 
            onClick={onRefresh} 
            size="small" 
            sx={{ 
              p: 0,
              color: 'text.secondary',
              '&:hover': {
                color: 'primary.main',
              }
            }}
          >
            <RefreshIcon sx={{ fontSize: 25 }} />
          </IconButton>
        ) : (
          datePickerEnabled ? (
            <TextField
              type="date"
              size="small"
              value={selectedDate || (displayData.reportDate ? new Date(displayData.reportDate).toISOString().slice(0, 10) : '')}
              onChange={(e) => onDateChange && onDateChange(e.target.value)}
              inputProps={{ max: new Date().toISOString().slice(0, 10) }}
              sx={{
                width: isMobile ? 130 : 160,
                minWidth: isMobile ? 130 : 160,
                minHeight: "25px",
                '& .MuiOutlinedInput-root': {
                  borderRadius: 2,
                  backgroundColor: theme.palette.background.paper,
                  '&:hover .MuiOutlinedInput-notchedOutline': {
                    borderColor: theme.palette.primary.main,
                  },
                  '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                    borderColor: theme.palette.primary.main,
                    borderWidth: 2,
                  },
                },
                '& .MuiOutlinedInput-notchedOutline': {
                  borderColor: theme.palette.divider,
                },
                '& input': { 
                  fontSize: isMobile ? '0.9rem' : '0.95rem',
                  padding: isMobile ? '3px 8px' : '4px 6px',
                  minHeight: isMobile ? 20 : 30,
                  color: theme.palette.text.primary,
                  colorScheme: theme.palette.mode === 'dark' ? 'dark' : 'light',
                },
                '& input::-webkit-calendar-picker-indicator': {
                  border: 'none',
                  cursor: 'pointer',
                  opacity: 0.8,
                  width: isMobile ? '14px' : '16px',
                  height: isMobile ? '14px' : '16px',
                  '&:hover': {
                    opacity: 1,
                  },
                },
                '& input[type="date"]::-webkit-datetime-edit': {
                  minHeight: '20px',
                },
              }}
            />
          ) : (
            <Typography
              variant="body2"
              sx={{
                color: 'text.secondary',
                fontSize: isMobile ? '0.875rem' : '1rem',
                fontWeight: 500,
              }}
            >
              {formatDate(displayData.reportDate)}
            </Typography>
          )
        )}
      </Box>
      
      <CardContent sx={{ p: isMobile ? 2 : 3 }}>
        <Typography 
          variant="h6" 
          gutterBottom 
          sx={{ 
            mb: isMobile ? 2 : 3, 
            fontWeight: 'bold',
            fontSize: isMobile ? '1.1rem' : '1.25rem'
          }}
        >
          {title}
        </Typography>

        {/* 四个主要指标 */}
        <Grid container spacing={isMobile ? 1 : 2} sx={{ mb: isMobile ? 2 : 3 }}>
          {/* CPU Usage */}
          <Grid item xs={6}>
            <Box sx={{ textAlign: 'center' }}>
              <CpuIcon sx={{ 
                fontSize: isMobile ? 30 : 40, 
                color: 'primary.main', 
                mb: 0.5 
              }} />
              <Typography 
                variant="h4" 
                sx={{ 
                  fontWeight: 'bold', 
                  mb: 0.5,
                  fontSize: isMobile ? '1.5rem' : '2.125rem'
                }}
              >
                {displayData.cpuUsage}%
              </Typography>
              <Typography 
                variant="body2" 
                color="text.secondary"
                sx={{ fontSize: isMobile ? '0.75rem' : '0.875rem' }}
              >
                CPU Usage
              </Typography>
              <LinearProgress 
                variant="determinate" 
                value={displayData.cpuUsage} 
                color={getProgressColor(displayData.cpuUsage)}
                sx={{ 
                  mt: 0.5, 
                  height: isMobile ? 6 : 8, 
                  borderRadius: 4 
                }}
              />
            </Box>
          </Grid>

          {/* Memory Usage */}
          <Grid item xs={6}>
            <Box sx={{ textAlign: 'center' }}>
              <MemoryIcon sx={{ 
                fontSize: isMobile ? 30 : 40, 
                color: 'secondary.main', 
                mb: 0.5 
              }} />
              <Typography 
                variant="h4" 
                sx={{ 
                  fontWeight: 'bold', 
                  mb: 0.5,
                  fontSize: isMobile ? '1.5rem' : '2.125rem'
                }}
              >
                {calculateMemoryUsage(displayData.memoryUsage, displayData.memoryAvailable)}%
              </Typography>
              <Typography 
                variant="body2" 
                color="text.secondary"
                sx={{ fontSize: isMobile ? '0.75rem' : '0.875rem' }}
              >
                Memory Usage
              </Typography>
              <LinearProgress 
                variant="determinate" 
                value={calculateMemoryUsage(displayData.memoryUsage, displayData.memoryAvailable)} 
                color={getProgressColor(calculateMemoryUsage(displayData.memoryUsage, displayData.memoryAvailable))}
                sx={{ 
                  mt: 0.5, 
                  height: isMobile ? 6 : 8, 
                  borderRadius: 4 
                }}
              />
            </Box>
          </Grid>

          {/* Disk Usage */}
          <Grid item xs={6}>
            <Box sx={{ textAlign: 'center' }}>
              <StorageIcon sx={{ 
                fontSize: isMobile ? 30 : 40, 
                color: 'info.main', 
                mb: 0.5 
              }} />
              <Typography 
                variant="h4" 
                sx={{ 
                  fontWeight: 'bold', 
                  mb: 0.5,
                  fontSize: isMobile ? '1.5rem' : '2.125rem'
                }}
              >
                {formatPercentage(displayData.diskUsage, displayData.diskUsage + displayData.diskFree)}%
              </Typography>
              <Typography 
                variant="body2" 
                color="text.secondary"
                sx={{ fontSize: isMobile ? '0.75rem' : '0.875rem' }}
              >
                Disk Usage
              </Typography>
              <LinearProgress 
                variant="determinate" 
                value={formatPercentage(displayData.diskUsage, displayData.diskUsage + displayData.diskFree)} 
                color={getProgressColor(formatPercentage(displayData.diskUsage, displayData.diskUsage + displayData.diskFree))}
                sx={{ 
                  mt: 0.5, 
                  height: isMobile ? 6 : 8, 
                  borderRadius: 4 
                }}
              />
            </Box>
          </Grid>

          {/* API Count */}
          <Grid item xs={6}>
            <Box sx={{ textAlign: 'center' }}>
              <ApiIcon sx={{ 
                fontSize: isMobile ? 30 : 40, 
                color: 'success.main', 
                mb: 0.5 
              }} />
              <Typography 
                variant="h4" 
                sx={{ 
                  fontWeight: 'bold', 
                  mb: 0.5,
                  fontSize: isMobile ? '1.5rem' : '2.125rem'
                }}
              >
                {formatNumber(displayData.apiCount)}
              </Typography>
              <Typography 
                variant="body2" 
                color="text.secondary"
                sx={{ fontSize: isMobile ? '0.75rem' : '0.875rem' }}
              >
                API Calls
              </Typography>
              {(() => {
                const apiProgress = apiMax7 > 0 ? Math.round((displayData.apiCount / apiMax7) * 100) : 0;
                return (
                  <LinearProgress 
                    variant="determinate" 
                    value={apiProgress}
                    color={getProgressColor(apiProgress)}
                    sx={{ 
                      mt: 0.5, 
                      height: isMobile ? 6 : 8, 
                      borderRadius: 4 
                    }}
                  />
                );
              })()}
            </Box>
          </Grid>
        </Grid>

        {/* 四个小指标 */}
        <Grid container spacing={isMobile ? 0.5 : 1}>
          <Grid item xs={6}>
            <Box sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              gap: 0.5,
              flexDirection: 'row',
              textAlign: 'left'
            }}>
              <PersonIcon sx={{ 
                fontSize: isMobile ? 16 : 20, 
                color: 'primary.main' 
              }} />
              <Typography 
                variant="body2" 
                sx={{ 
                  flexGrow: 1,
                  fontSize: isMobile ? '0.7rem' : '0.875rem'
                }}
              >
                Anonymous:
              </Typography>
              <Chip 
                label={formatNumber(displayData.anonymousCount)} 
                size={isMobile ? "small" : "small"}
                color="primary" 
                variant="outlined"
                sx={{ 
                  fontSize: isMobile ? '0.7rem' : '0.75rem',
                  height: isMobile ? 20 : 24
                }}
              />
            </Box>
          </Grid>

          <Grid item xs={6}>
            <Box sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              gap: 0.5,
              flexDirection: 'row',
              textAlign: 'left'
            }}>
              <ArticleIcon sx={{ 
                fontSize: isMobile ? 16 : 20, 
                color: 'secondary.main' 
              }} />
              <Typography 
                variant="body2" 
                sx={{ 
                  flexGrow: 1,
                  fontSize: isMobile ? '0.7rem' : '0.875rem'
                }}
              >
                Blog:
              </Typography>
              <Chip 
                label={formatNumber(displayData.blogCount)} 
                size={isMobile ? "small" : "small"}
                color="secondary" 
                variant="outlined"
                sx={{ 
                  fontSize: isMobile ? '0.7rem' : '0.75rem',
                  height: isMobile ? 20 : 24
                }}
              />
            </Box>
          </Grid>

          <Grid item xs={6}>
            <Box sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              gap: 0.5,
              flexDirection: 'row',
              textAlign: 'left'
            }}>
              <ChatbotIcon sx={{ 
                fontSize: isMobile ? 16 : 20, 
                color: 'info.main' 
              }} />
              <Typography 
                variant="body2" 
                sx={{ 
                  flexGrow: 1,
                  fontSize: isMobile ? '0.7rem' : '0.875rem'
                }}
              >
                Chatbot:
              </Typography>
              <Chip 
                label={formatNumber(displayData.chatbotCount)} 
                size={isMobile ? "small" : "small"}
                color="info" 
                variant="outlined"
                sx={{ 
                  fontSize: isMobile ? '0.7rem' : '0.75rem',
                  height: isMobile ? 20 : 24
                }}
              />
            </Box>
          </Grid>

          <Grid item xs={6}>
            <Box sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              gap: 0.5,
              flexDirection: 'row',
              textAlign: 'left'
            }}>
              <LocationIcon sx={{ 
                fontSize: isMobile ? 16 : 20, 
                color: 'success.main' 
              }} />
              <Typography 
                variant="body2" 
                sx={{ 
                  flexGrow: 1,
                  fontSize: isMobile ? '0.7rem' : '0.875rem'
                }}
              >
                My IPs:
              </Typography>
              <Chip 
                label={formatNumber(displayData.myIpCount)} 
                size={isMobile ? "small" : "small"}
                color="success" 
                variant="outlined"
                sx={{ 
                  fontSize: isMobile ? '0.7rem' : '0.75rem',
                  height: isMobile ? 20 : 24
                }}
              />
            </Box>
          </Grid>
        </Grid>
      </CardContent>
    </Card>
  );
};

export default ServerInfoWidget;
